  1357→#[cfg(test)]
  1358→mod reference_implementation {
  1359→    //! Reference implementation for validating COLMAP intrinsics parsing
  1360→    //!
  1361→    //! This serves as documentation for the expected precision and behavior.
  1362→
  1363→    use nalgebra::{Matrix3, Vector3};
  1364→
  1365→    /// Expected precision for intrinsic parameters
  1366→    pub const FOCAL_LENGTH_PRECISION: f32 = 0.01; // pixels
  1367→    pub const PRINCIPAL_POINT_PRECISION: f32 = 0.01; // pixels
  1368→
  1369→    /// Expected precision for extrinsic parameters
  1370→    pub const ROTATION_PRECISION_DEGREES: f32 = 0.1; // degrees
  1371→    pub const TRANSLATION_PRECISION: f32 = 0.001; // units
  1372→
  1373→    /// Verify intrinsics meet precision requirements
  1374→    pub fn verify_intrinsics_precision(
  1375→        parsed_fx: f32,
  1376→        parsed_fy: f32,
  1377→        parsed_cx: f32,
  1378→        parsed_cy: f32,
  1379→        ground_truth_fx: f32,
  1380→        ground_truth_fy: f32,
  1381→        ground_truth_cx: f32,
  1382→        ground_truth_cy: f32,
  1383→    ) -> bool {
  1384→        let fx_error = (parsed_fx - ground_truth_fx).abs();
  1385→        let fy_error = (parsed_fy - ground_truth_fy).abs();
  1386→        let cx_error = (parsed_cx - ground_truth_cx).abs();
  1387→        let cy_error = (parsed_cy - ground_truth_cy).abs();
  1388→
  1389→        fx_error < FOCAL_LENGTH_PRECISION
  1390→            && fy_error < FOCAL_LENGTH_PRECISION
  1391→            && cx_error < PRINCIPAL_POINT_PRECISION
  1392→            && cy_error < PRINCIPAL_POINT_PRECISION
  1393→    }
  1394→
  1395→    /// Verify rotation matrix is orthonormal
  1396→    pub fn verify_rotation_orthonormal(rotation: &Matrix3<f32>, tolerance: f32) -> bool {
  1397→        let rt_r: Matrix3<f32> = rotation.transpose() * rotation;
  1398→        let identity: Matrix3<f32> = Matrix3::identity();
  1399→
  1400→        for i in 0..3 {
  1401→            for j in 0..3 {
  1402→                let diff = (rt_r[(i, j)] - identity[(i, j)]).abs();
  1403→                if diff > tolerance {
  1404→                    return false;
  1405→                }
  1406→            }
  1407→        }
  1408→
  1409→        // Also verify determinant is +1 (proper rotation)
  1410→        (rotation.determinant() - 1.0).abs() < tolerance
  1411→    }
  1412→
  1413→    /// Compute rotation error in degrees between two rotation matrices
  1414→    pub fn rotation_error_degrees(r1: &Matrix3<f32>, r2: &Matrix3<f32>) -> f32 {
  1415→        // Error rotation: R_error = R1^T * R2
  1416→        let r_error = r1.transpose() * r2;
  1417→
  1418→        // Extract angle from rotation matrix using trace
  1419→        // trace(R) = 1 + 2*cos(theta)
  1420→        let trace = r_error[(0, 0)] + r_error[(1, 1)] + r_error[(2, 2)];
  1421→        let cos_theta = (trace - 1.0) / 2.0;
  1422→        let cos_theta_clamped = cos_theta.clamp(-1.0, 1.0);
  1423→        let theta_rad = cos_theta_clamped.acos();
  1424→
  1425→        theta_rad.to_degrees()
  1426→    }
  1427→
  1428→    /// Verify extrinsics meet precision requirements
  1429→    pub fn verify_extrinsics_precision(
  1430→        parsed_rotation: &Matrix3<f32>,
  1431→        parsed_translation: &Vector3<f32>,
  1432→        ground_truth_rotation: &Matrix3<f32>,
  1433→        ground_truth_translation: &Vector3<f32>,
  1434→    ) -> bool {
  1435→        // Check rotation error
  1436→        let rotation_error = rotation_error_degrees(parsed_rotation, ground_truth_rotation);
  1437→        if rotation_error >= ROTATION_PRECISION_DEGREES {
  1438→            return false;
  1439→        }
  1440→
  1441→        // Check translation error
  1442→        let translation_error = (parsed_translation - ground_truth_translation).norm();
  1443→        if translation_error >= TRANSLATION_PRECISION {
  1444→            return false;
  1445→        }
  1446→
  1447→        true
  1448→    }
  1449→}
