            }
        }

        println!();
    }

    // Test Case 2: Very large scales (1e6)
    {
        println!("Test 2 - Very large scales (1e6):");

        // Scale in log-space: log(1e6) ≈ 13.8
        let large_scale = 1e6f32;
        let log_scale = Vector3::new(large_scale.ln(), large_scale.ln(), large_scale.ln());
