        println!("  Actual scale: ({:.3e}, {:.3e}, {:.3e})", sx, sy, sz);
        println!("  Rotation: 45° around Y-axis");
        println!("  Covariance:\n{}", covariance);

        // 1. Verify no NaN or Inf
        for i in 0..3 {
